cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
// Try broader search
const rows = db.prepare(\"SELECT user_id, name, email, address_json FROM users WHERE skill_ids_json LIKE '%tau2Retail%'\").all();
rows.forEach(r => {
  const addr = JSON.parse(r.address_json || '{}');
  if (addr.zip === '94110' || (r.name && r.name.toLowerCase().includes('alicia'))) {
    console.log(JSON.stringify({...r, address: addr}, null, 2));
  }
});
db.close();
"

