cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
// Search by email across all users
const rows = db.prepare(\"SELECT user_id, name, email, address_json, skill_ids_json FROM users WHERE email = 'alicia.morgan@email.com'\").all();
rows.forEach(r => console.log(JSON.stringify(r, null, 2)));
if (rows.length === 0) {
  // Try partial match
  const partial = db.prepare(\"SELECT user_id, name, email FROM users WHERE email LIKE '%alicia%' OR email LIKE '%morgan%'\").all();
  console.log('Partial matches:', JSON.stringify(partial, null, 2));
}
db.close();
"

